const staticData = $getWorkflowStaticData('global');
staticData.sent = staticData.sent || {};
const candidates = $('Filter Already Notified').all();

let failures = 0;
$input.all().forEach((item, i) => {
  if (item.json.error) {
    failures += 1;
    return;
  }
  const idx = item.pairedItem && item.pairedItem.item !== undefined ? item.pairedItem.item : i;
  const alert = candidates[idx].json;
  staticData.sent[alert.dedupKey] = { at: new Date().toISOString(), state: alert.stateValue };
});

if (failures > 0) {
  throw new Error(`${failures} alert email(s) failed to send; successful ones were recorded, failed ones will retry next run.`);
}
return [{ json: { saved: $input.all().length } }];
